def solution(grid_input):
    """
    Solution for the apartment rectangle problem.
    We need to remove minimum walls so that all rooms are rectangles.

    Approach: For each connected component of free spaces, if it's not already
    a rectangle (i.e., there are '*' within its bounding box), we remove those
    walls to make it rectangular.
    """
    import sys
    from collections import deque

    lines = grid_input.strip().split('\n')
    n, m = map(int, lines[0].split())

    grid = [list(line) for line in lines[1:n+1]]

    def get_bounding_boxes():
        """Get all rectangular rooms by filling bounding boxes of connected components"""
        solution_grid = [row[:] for row in grid]
        visited = [[False] * m for _ in range(n)]

        for i in range(n):
            for j in range(m):
                if grid[i][j] == '.' and not visited[i][j]:
                    # BFS to find all cells in this connected component
                    visited[i][j] = True
                    cells = []
                    q = deque([(i, j)])

                    while q:
                        x, y = q.popleft()
                        cells.append((x, y))

                        for dx, dy in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                            nx, ny = x + dx, y + dy
                            if 0 <= nx < n and 0 <= ny < m and not visited[nx][ny] and grid[nx][ny] == '.':
                                visited[nx][ny] = True
                                q.append((nx, ny))

                    # Find bounding box
                    if cells:
                        min_r, max_r = min(c[0] for c in cells), max(c[0] for c in cells)
                        min_c, max_c = min(c[1] for c in cells), max(c[1] for c in cells)

                        # Fill the bounding box with free space
                        for r in range(min_r, max_r + 1):
                            for c in range(min_c, max_c + 1):
                                solution_grid[r][c] = '.'

        return solution_grid

    return '\n'.join(''.join(row) for row in get_bounding_boxes())
