                return '0'

    # Detect cycles in super graph
    def detect_cycle():
        visited = {}
        rec_stack = set()

        def dfs(u):
            visited[u] = u
            rec_stack.add(u)
            for v in super_edges[u]:
                if v not in visited:
                    if dfs(v):
                        return True
                elif v in rec_stack:
                    return True
            rec_stack.remove(u)
            return False

        for i in range(num_chains):
            if i not in visited:
                if dfs(i):
                    return True
        return False

    if detect_cycle():
        return '0'

    # Topological sort on super graph
    in_degree = defaultdict(int)
    for u in super_edges:
        for v in super_edges[u]:
            in_degree[v] += 1
    for i in range(num_chains):
        if i not in in_degree:
            in_degree[i] = 0

    queue = [i for i in range(num_chains) if in_degree[i] == 0]
    result_chains = []

    while queue:
        u = queue.pop(0)
        result_chains.append(chains_map[u])
        for v in super_edges[u]:
            in_degree[v] -= 1
            if in_degree[v] == 0:
                queue.append(v)

    if len(result_chains) < num_chains:
        return '0'  # Cycle - but we already checked

    # Build final result
    result = []
    for chain in result_chains:
        for node in chain:
            result.append(node)

    return ' '.join(map(str, result))
