def solution_working(input_str):
    n, m, r, k = map(int, input_str.split())

    # Calculate count_x: for each column i, how many scoop positions cover it
    count_x = []
    for i in range(1, n + 1):
        # x must satisfy: x <= i < x + r  =>  x in [i-r+1, i]
        # Also x in [1, n-r+1]
        x_min = max(1, i - r + 1)
        x_max = min(i, n - r + 1)
        count_x.append(x_max - x_min + 1)

    # Same for y
    count_y = []
    for j in range(1, m + 1):
        y_min = max(1, j - r + 1)
        y_max = min(j, m - r + 1)
        count_y.append(y_max - y_min + 1)

    # Sort both in descending order
    count_x.sort(reverse=True)
    count_y.sort(reverse=True)

    # Sum the top k products
    top_sum = sum(count_x[i] * count_y[i] for i in range(k))

    # Divide by total number of scoop positions
    num_positions = (n - r + 1) * (m - r + 1)
    result = top_sum / num_positions

    return f"{result:.10f}"
