Looking at this problem, I need to find a minimum-weight shortest-path tree from a given source vertex. This requires:

1. Computing shortest path distances from the source using Dijkstra's algorithm
2. For each vertex (except the source), selecting exactly one parent edge that lies on some shortest path
3. Among all valid parent edges for each vertex, choosing the one with minimum weight
4. Summing up these weights and outputting the edge indices

Let me write the solution:

```python
def solution(input_str):
    lines = input_str.strip().split('\n')
    n, m = map(int, lines[0].split())

    # Build adjacency list and edge list (storing original indices)
    adj = [[] for _ in range(n + 1)]
    edges = []  # (u, v, w, original_index)

    for i in range(1, m + 1):
        u, v, w = map(int, lines[i].split())
        edges.append((u, v, w, i))
        adj[u].append((v, w))
        adj[v].append((u, w))

    start = int(lines[m + 1])

    import heapq
    INF = float('inf')

    # Dijkstra's algorithm to compute shortest paths from start
    dist = [INF] * (n + 1)
    dist[start] = 0
    pq = [(0, start)]

    while pq:
        d, u = heapq.heappop(pq)
        if d > dist[u]:
            continue
        for v, w in adj[u]:
            if dist[u] + w < dist[v]:
                dist[v] = dist[u] + w
                heapq.heappush(pq, (dist[v], v))

    # For each vertex, find the minimum weight edge that can serve as parent
    # on a shortest path
    edge_indices = []
    min_weight = 0

    for v in range(1, n + 1):
        if v == start:
            continue

        min_w = INF
        edge_idx = -1

        # Check each edge to see if it can be a parent edge for v
        for (u, x, w, idx) in edges:
            # One endpoint must be v
            if u == v:
                parent = x
            elif x == v:
                parent = u
            else:
                continue

            # Check if this edge is on a shortest path from start to v
            # dist[parent] + w == dist[v] means parent is a valid parent for v
            if dist[parent] + w == dist[v]:
                # Choose the edge with minimum weight
                if w < min_w:
                    min_w = w
                    edge_idx = idx

        if edge_idx != -1:
            min_weight += min_w
            edge_indices.append(edge_idx)

    return f"{min_weight}\n{' '.join(map(str, edge_indices))}"
