    # Check for empty clauses (invalid)
    for clause in clauses:
        if not clause:
            return "NO"

    if not clauses:
        return "YES\n" + "0" * m

    # Build 2-SAT graph
    # Node i represents xi=true, node i+m represents xi=false
    # For clause (l1 OR l2 OR ... OR lk), add neg(-li) -> lj for all j != i
    # neg(1) = 0 for implication (true -> anything)
    # neg(-1) = 1 (use 1 to represent negation of -1)

    # Actually use negation in implication graph properly:
    # For clause (L1 OR L2 OR ... OR Lk), add edge neg(Li) -> Lj for all i,j
    # where neg(Li) = if Li is positive x_v then -x_v (which is x_v+m) else x_v

    graph = [[] for _ in range(2 * m)]

    def neg_node(lit):
        # lit can be x_v or -x_v
        v = abs(lit)
        if lit > 0:
            return v  # represents xi if xi is true, negation is -xi
        else:
            return v + m  # represents -xi, negation is xi

    def lit_to_node(lit):
        v = abs(lit)
        if lit > 0:
            return v - 1  # 0-indexed node for xi=true
        else:
            return (v - 1) + m  # 0-indexed node for xi=false

