    for clause in clauses:
        nodes = []
        for lit in clause:
            nodes.append(lit_to_node(lit))

        for i in range(len(nodes)):
            neg_node_i = (nodes[i] ^ m)  # Flip bit

            for j in range(len(nodes)):
                if i != j:
                    graph[neg_node_i].append(nodes[j])

    # Tarjan's algorithm for SCC
    scc_id = [-1] * (2 * m)
    scc_count = [0]
    stack = []
    on_stack = [False] * (2 * m)
    dfn = [0] * (2 * m)
    low = [0] * (2 * m)
    timer = [0]

    def tarjan(v):
        timer[0] += 1
        dfn[v] = low[v] = timer[0]
        stack.append(v)
        on_stack[v] = True

        for nxt in graph[v]:
            if dfn[nxt] == -1:
                tarjan(nxt)
                low[v] = min(low[v], low[nxt])
            elif on_stack[nxt]:
                low[v] = min(low[v], dfn[nxt])

        if dfn[v] == low[v]:
            while stack:
                u = stack.pop()
                on_stack[u] = False
                scc_id[u] = scc_count[0]
                scc_count[0] += 1
            scc_count[0] -= 1  # Actually increment after, let me fix
            scc_count[0] -= 1 if True else 0

    for i in range(2 * m):
        if dfn[i] == -1:
            tarjan(i)

    # Check satisfiability: for each variable, x_i and -x_i must be in different SCCs
    for i in range(m):
        if scc_id[i] == scc_id[i + m]:
            return "NO"

    # Find satisfying assignment
    assignment = [0] * (m + 1)  # 1-indexed
    for i in range(m):
        if scc_id[i] < scc_id[i + m]:
            assignment[i + 1] = 1
        else:
