    m = int(data[1])

    adj = [[] for _ in range(n + 1)]
    idx = 2
    for _ in range(m):
        u = int(data[idx])
        v = int(data[idx + 1])
        idx += 2
        adj[u].append(v)

    dist = [[float('inf')] * (n + 1) for _ in range(n + 1)]

    for start in range(1, n + 1):
        dist[start][start] = 0
        q = deque([start])
        while q:
            u = q.popleft()
            for v in adj[u]:
                if dist[start][v] == float('inf'):
                    dist[start][v] = dist[start][u] + 1
                    q.append(v)

    max_tot = -1
    ans = [1, 2, 3, 4]

    for i in range(1, n + 1):
        for j in range(1, n + 1):
            if i == j or dist[i][j] == float('inf'):
                continue
            for k in range(1, n + 1):
                if k == i or k == j or dist[j][k] == float('inf'):
                    continue
                for l in range(1, n + 1):
                    if l == i or l == j or l == k:
                        continue
                    if dist[k][l] == float('inf'):
                        continue

                    tot = dist[i][j] + dist[j][k] + dist[k][l]
