        center = [0.0, 0.0, 0.0]
        center[0] = (A[0] * det3([B, B, p2]) + p1[0] * det3(B, p2, p3)) / (2 * norm_sq)
        center[1] = (A[1] * det3([B, B, p2]) + p2[1] * det3(B, p2, p3)) / (2 * norm_sq)
        center[2] = (A[2] * det3([B, B, p2]) + p3[2] * det3(B, p2, p3)) / (2 * norm_sq)

        return center[0], center[1], center[2], dist_sq(center, p1)

    def solve_4(p1, p2, p3, p4):
        A = [[-p[0], -p[1], -p[2], 1] for p in [p1, p2, p3, p4]]
        try:
            import numpy as np
            M = np.array(A)
            c = np.linalg.solve(M, [0, 0, 0, -1])
            r2 = dist_sq((c[0], c[1], c[2]), p1) / 4
            return c[0], c[1], c[2], r2
        except:
            return solve_3(p1, p2, p3)

    def rec(S, R):
        if len(R) >= 4:
            balls = []
            if len(R) == 1:
                balls.append(solve_1(R[0]))
            elif len(R) == 2:
                balls.append(solve_2(R[0], R[1]))
            elif len(R) == 3:
                balls.append(solve_3(R[0], R[1], R[2]))
            elif len(R) == 4:
                balls.append(solve_4(R[0], R[1], R[2], R[3]))

            # Check which ball works for all S
            for c1, r2 in balls:
                max_d2 = 0
                valid = True
                for p in S:
                    d2 = dist_sq((c1, c1, c1), p)
                    if d2 > r2:
                        valid = False
                        break
                if valid:
                    return (c1, c1, c1), r2
            return None, float('inf')
        elif len(S) == 0:
            if len(R) == 0:
                return None, 0.0
            elif len(R) == 1:
                return solve_1(R[0])
            elif len(R) == 2:
                return solve_2(R[0], R[1])
            elif len(R) == 3:
                return solve_3(R[0], R[1], R[2])
            return None, float('inf')

        p = S[-1]
        c, r2 = rec(S[:-1], R)
        if r2 == float('inf') or dist_sq((c, c, c), p) > 1e-9:
            return rec(S[:-1], R + [p])
        return (c, c, c), r2

    result = rec(points, [])
    c, r2 = result
    if c is None:
        # Fallback: centroid
        cx = sum(p[0] for p in points) / n
        cy = sum(p[1] for p in points) / n
        cz = sum(p[2] for p in points) / n
        return f"{cx:.6f} {cy:.6f} {cz:.6f}\n"
    return f"{cx:.6f} {cy:.6f} {cz:.6f}\n"


