def solution(input_str):
    lines = input_str.strip().split('\n')
    ts, tf, t = map(int, lines[0].split())
    n = int(lines[1])
    arrivals = list(map(int, lines[2].split())) if n > 0 else []

    # We need to find an arrival time for Vasya that minimizes his waiting time in queue
    # Vasya must be served before receptionist closes (at tf)
    # If multiple visitors arrive at same time, Vasya queues after them

    # Strategy: try various candidate arrival times, check if Vasya can be served, and minimize wait

    def can_be_served(vasya_arr):
        """Returns (is_served, wait_time)"""
        vasya_arr = max(vasya_arr, ts)  # Must be at least ts to be served

        if vasya_arr >= tf:
            return False, float('inf')

        combined = []  # (arrival_time, is_vasya)
        for arr in arrivals:
            # Only consider visitors who would definitely arrive before Vasya's service ends
            combined.append((arr, 0))
        combined.append((vasya_arr, 1))  # Vasya has higher priority when at same time (he comes after)

        # Sort by arrival_time, then is_vasya (0 comes before 1, meaning regular visitors jump ahead)
        combined.sort(key=lambda x: (x[0], x[1]))

        last_finish = ts - 1
        has_vasya = False
        vasya_start = -1

        for arr_time, is_vasya in combined:
            if arr_time < ts:
                # Visitor arrived before opening, effectively arrives at ts
                arr_time = ts

            start = max(arr_time, last_finish + 1)
            finish = start + t

            if is_vasya:
                if finish > tf - 1:  # Must finish before tf (tf-1 is last working minute)
                    return False, float('inf')
                vasya_start = start
                has_vasya = True
            elif finish > tf - 1:
                # Regular visitor can't be served, doesn't matter for Vasya
                pass

            last_finish = finish

        if not has_vasya:
            return False, float('inf')

        wait = vasya_start - vasya_arr
        if wait < 0:
            wait = 0  # Negative means he was in line from opening

        return True, wait

    # Generate candidate arrival times
    candidates = set()
    candidates.add(ts)

    for arr in arrivals:
        candidates.add(arr)
        if ts <= arr:
            # Try arriving after service of this visitor
            candidates.add(arr + t)

    # Try a few more strategic times
    for i in range(n + 1):
        candidates.add(ts + i * t if ts + i * t < tf else ts)

    best_arrival = ts
    best_wait = float('inf')

    for cand in sorted(candidates):
        if cand < ts:
            cand = ts
        if cand >= tf:
            continue

        is_served, wait = can_be_served(cand)
        if is_served:
            if wait < best_wait:
                best_wait = wait
                best_arrival = cand
            elif wait == best_wait:
                # Prefer later time if wait is same and after others would leave
                if best_arrival < cand and best_arrival >= ts:
                    best_arrival = cand

    return f"{best_arrival}\n"


