        for _ in range(n):
            matrix.append(list(map(int, lines[idx].split())))
            idx += 1

        ops_str = lines[idx] if idx < len(lines) else ""
        idx += 1

        current_matrix = [row[:] for row in matrix]

        for op in ops_str:
            # Using 1-indexed formula translation to 0-indexed
            if op == 'R':
                # Cyclically shift columns right: new[j] = old[j-1]
                # Position j moves to j+1 (mod n)
                for r in range(n):
                    row = current_matrix[r]
                    current_matrix[r] = [row[-1]] + row[:-1]

            elif op == 'L':
                # Cyclically shift columns left: new[j] = old[j+1]
                for r in range(n):
                    row = current_matrix[r]
                    current_matrix[r] = row[1:] + [row[0]]

            elif op == 'D':
                # Cyclically shift rows down: new[r] = old[r-1]
                # Row r moves to r+1 (mod n)
                if n > 1:
                    for c in range(n):
                        row, next_row = current_matrix[c % n], current_matrix[(c + 1) % n]
                        current_matrix[c % n] = [row[j] for j in range(n)]
                        current_matrix[(c + 1) % n] = next_row
                    new_matrix = [current_matrix[(r - 1) % n] for r in range(n)]
                    current_matrix = new_matrix
                elif n == 1:
                    pass

            elif op == 'U':
                # Cyclically shift rows up: new[r] = old[r+1]
                if n > 1:
                    new_matrix = [current_matrix[(r + 1) % n] for r in range(n)]
                    current_matrix = new_matrix
                elif n == 1:
                    pass

            elif op == 'I':
                # Invert permutation in each row
                inv_row = []
                for row in current_matrix:
                    inv = [0] * n
                    for c in range(n):
                        inv[row[c] - 1] = c + 1
                    inv_row.append(inv)
                current_matrix = inv_row

            elif op == 'C':
                # Invert permutation in each column
                inv_col = []
                for c in range(n):
                    col = [current_matrix[r][c] for r in range(n)]
                    inv = [0] * n
                    for r in range(n):
                        inv[col[r] - 1] = r + 1
                    for r in range(n):
                        inv_col.append(inv[r - 1])
                current_matrix = [[inv_col[c][r] for r in range(n)] for c in range(n)]

        test_output = '\n'.join(' '.join(map(str, row)) for row in current_matrix)
        output_lines.append(test_output)

    return '\n\n'.join(output_lines)

