# Corrected solution
def solution(input_str):
    from collections import Counter

    if '\n' in input_str:
        parts = input_str.strip().split('\n')
    else:
        parts = input_str.strip().split()

    if len(parts) < 2:
        return ""

    received = parts[0]
    substring = parts[1]
    m = len(received)

    for d in range(1, m + 1):
        k_str = str(d)
        k_len = len(k_str)
        if m != d + k_len:
            continue

        freq = Counter(received)
        for ch in k_str:
            if freq[ch] > 0:
                freq[ch] -= 1
            else:
                continue

        if list(freq.values()) == [0] * len(freq):
            continue

        sorted_freq = sorted(freq.items(), key=lambda x: (x[0], x[1]))
        result = []
        for digit, count in sorted_freq:
            result.extend([digit] * count)

        if len(result) == d:
            return "".join(result)

    return ""
